css:
.loader{
  --td-dot: calc(var(--loader-size, 56px) / 5.6);
  --td-gap: calc(var(--loader-size, 56px) / 12);
  display:inline-flex;
  align-items:center;
  justify-content:center;
  gap:var(--td-gap);
  width:var(--loader-size, 56px);
  height:var(--loader-size, 56px);
}
.loader i{
  width:var(--td-dot);
  height:var(--td-dot);
  border-radius:50%;
  background-color:var(--loader-color, #6366f1);
}
.loader i{animation:td-floating var(--loader-speed, 3s) infinite ease-in-out}
.loader i:nth-child(2){animation-delay:calc(var(--loader-speed, 3s) / 12)}
.loader i:nth-child(3){animation-delay:calc(var(--loader-speed, 3s) / 6)}
@keyframes td-floating{
  0%,100%{transform:translateY(0)}
  50%{transform:translateY(calc(var(--td-dot) * -0.8))}
}
